input.command:
cd /Users/zhupanov/larch1
echo "=== Issues referencing #3482 (the motivating run) or auto-apply ==="
gh issue list --state all --limit 60 --search '3482 OR "auto-apply" OR "auto apply"' --json number,title,state 2>/dev/null | jq -r '.[] | "#\(.number) [\(.state)] \(.title)"' || true
echo
echo "=== #3513 native blocked-by edges ==="
gh api graphql -f query='
query {
  repository(owner:"character-ai", name:"larch") {
    issue(number:3513) {
      title
      timelineItems(itemTypes:[CONNECTED_EVENT,CROSS_REFERENCED_EVENT], first:30) {
        nodes { __typename }
      }
    }
  }
}' 2>/dev/null | jq -r '.data.repository.issue.title' 2>/dev/null || echo "graphql blocked-by lookup not available"
echo
echo "=== Sub-issue/blocked-by via REST (blocked_by) ==="
gh api "repos/character-ai/larch/issues/3513" --jq '{title: .title, body_has_blocked: (.body|test("Blocked by"))}' 2>/dev/null || true
